import java.io.*;
import java.util.*;

public class Main {
    static BufferedReader in = new BufferedReader(new InputStreamReader(System.in));
    static StringTokenizer tokens = new StringTokenizer("");

    static String next() throws IOException {
        while (!tokens.hasMoreTokens()) {
            tokens = new StringTokenizer(in.readLine());
        }
        return tokens.nextToken();
    }

    public static void main(String[] args) throws IOException {
        long n = Long.parseLong(next());
        long k = Long.parseLong(next());
        long[] a = new long[(int) n];
        for (int i = 0; i < a.length; i++) a[i] = Long.parseLong(next());

        long[] vals = new long[64];
        long[] cnts = new long[64];
        int size = 0;
        long total = 0;
        for (int idx = 0; idx < n; idx++) {
            long x = a[idx];
            long[] nv = new long[64];
            long[] nc = new long[64];
            int ns = 0;
            for (int i = 0; i < size; i++) {
                long w = vals[i] & x;
                if (ns > 0 && nv[ns - 1] == w) nc[ns - 1] += cnts[i];
                else {
                    nv[ns] = w;
                    nc[ns] = cnts[i];
                    ns++;
                }
            }
            if (ns > 0 && nv[ns - 1] == x) nc[ns - 1] += 1;
            else {
                nv[ns] = x;
                nc[ns] = 1;
                ns++;
            }
            vals = nv;
            cnts = nc;
            size = ns;
            for (int i = 0; i < size; i++) if (vals[i] == k) total += cnts[i];
        }
        System.out.println(total);
    }
}
